'use strict';
const GAMES=globalThis.BUKGames;
let filter='all',query='',favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('buklabs-favorites'))||[]);}catch{}
const grid=document.getElementById('game-grid'),details=document.getElementById('details');
function draw(){
const shown=GAMES.filter(g=>(filter==='all'||filter===g.category||(filter==='favorites'&&favorites.has(g.id)))&&norm(g.name+' '+g.tag+' '+g.description).includes(norm(query)));
grid.innerHTML=shown.length?shown.map(g=>`<article class="game-card"><div class="cover cover-${g.color}"><a class="cover-link" href="game.html?game=${g.id}" aria-label="Conocer ${g.name}"><img src="${g.image}" alt="${g.name}: ${g.hook}" width="1536" height="1024" loading="lazy"></a><button class="fav ${favorites.has(g.id)?'active':''}" data-fav="${g.id}" aria-pressed="${favorites.has(g.id)}" aria-label="${favorites.has(g.id)?'Quitar':'Agregar'} ${g.name} ${favorites.has(g.id)?'de':'a'} favoritos">${favorites.has(g.id)?'♥':'♡'}</button></div><div class="game-info"><div class="game-tags"><span>${g.players}</span><span>·</span><span>${g.time}</span></div><h3>${g.name}</h3><p>${g.description}</p><div class="creator">Creado por <b>BUKLABS</b> · ${g.content}</div><div class="game-buttons"><a href="games/${g.id}/">Jugar ahora &nbsp; ↗</a><a class="detail-link" href="game.html?game=${g.id}">Ver detalles</a></div></div></article>`).join(''):`<div class="empty-state"><strong>${filter==='favorites'?'Tu selección empieza con un corazón.':'No encontramos ese juego.'}</strong><br>${filter==='favorites'?'Toca ♡ en los juegos que quieras guardar.':'Prueba con películas, palabras o reflejos.'}<br><button class="button lime" data-reset>Ver todos los juegos</button></div>`;
document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter);});document.getElementById('fav-count').textContent=favorites.size;
}
function norm(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function toast(s){const el=document.getElementById('catalog-toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2000);}
function info(g){details.innerHTML=`<button class="close" data-close aria-label="Cerrar">×</button><div class="eyebrow">CREADO POR BUKLABS</div><h2>${g.name}</h2><p>${g.players} · ${g.time} · ${g.content}</p><ol>${g.rules.map(x=>`<li>${x}</li>`).join('')}</ol><a class="button lime" href="games/${g.id}/">Jugar ahora →</a>`;details.showModal();}
document.addEventListener('click',e=>{const fav=e.target.closest('[data-fav]'),fil=e.target.closest('[data-filter]'),inf=e.target.closest('[data-info]');if(fav){const id=fav.dataset.fav;favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('buklabs-favorites',JSON.stringify([...favorites]));}catch{}draw();}if(fil){filter=fil.dataset.filter;draw();}if(inf)info(GAMES.find(g=>g.id===inf.dataset.info));if(e.target.closest('[data-close]'))details.close();if(e.target.closest('[data-reset]')){filter='all';query='';document.getElementById('search').value='';draw();}});
document.getElementById('search').addEventListener('input',e=>{query=e.target.value;draw();});
document.getElementById('nav-favs').onclick=()=>{filter='favorites';query='';document.getElementById('search').value='';draw();document.getElementById('juegos').scrollIntoView();};
document.getElementById('surprise').onclick=()=>{location.href=`games/${GAMES[Math.floor(Math.random()*GAMES.length)].id}/`;};
document.getElementById('about').onclick=()=>{details.innerHTML='<button class="close" data-close aria-label="Cerrar">×</button><div class="eyebrow">CREADO POR BUKLABS</div><h2>Un dispositivo.<br>Toda la mesa.</h2><p>BUKLABS Play reúne tres juegos de fiesta para jugar cara a cara. Abre un juego, agrega a tus participantes y empieza.</p><p>Funciona en navegadores de celulares, tablets y computadores. Puedes instalar la plataforma desde el botón «Instalar app» cuando tu navegador lo permita.</p><p>Espera «Listo sin conexión» antes de desconectarte. Las partidas y favoritos se guardan en este navegador; no se comparten entre dispositivos.</p><button class="button lime" data-close>Listo para jugar</button>';details.showModal();};
function recent(){try{const game=GAMES.find(g=>g.id===localStorage.getItem('buklabs-last-game'));document.getElementById('recent').innerHTML=game?`<div class="recent-bar"><span>Tu último juego: <strong>${game.name}</strong></span><a href="games/${game.id}/">Volver al juego →</a></div>`:'';}catch{}}
window.addEventListener('pageshow',recent);draw();recent();
